_PIPELINE_RANK_LOGGERS: Dict[str, logging.Logger] = {}


def _get_rank_logger(
    base_name: str = 'pipeline',
    logger_cache: Optional[Dict[str, logging.Logger]] = None,
    enable: bool = False,
) -> tuple[int, Optional[logging.Logger]]:
    if dist.is_available() and dist.is_initialized():
        rank = dist.get_rank()
    else:
        rank = 0

    if not enable:
        return rank, None

    cache = logger_cache if logger_cache is not None else _PIPELINE_RANK_LOGGERS

    logger_key = f'{base_name}.rank{rank}'
    logger = cache.get(logger_key)
    if logger is not None:
        return rank, logger

    work_dir = os.environ.get('MMDET_WORK_DIR', './work_dirs')
    try:
        runner = Runner.get_instance()
        if runner is not None and getattr(runner, 'work_dir', None):
            work_dir = runner.work_dir
    except Exception:
        pass

    log_dir = os.path.join(work_dir, 'rank_logs')
    os.makedirs(log_dir, exist_ok=True)
    log_path = os.path.join(log_dir, f'{base_name}_rank{rank}.log')

    logger = logging.getLogger(logger_key)
    if not logger.handlers:
        logger.setLevel(logging.INFO)
        logger.propagate = False
        handler = logging.FileHandler(log_path)
        formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        logger.addHandler(handler)

    cache[logger_key] = logger
    return rank, logger

def read_HSD(filename):
    data = np.fromfile('%s' % filename, dtype=np.int32)
    height = data[0]
    width = data[1]
    SR = data[2]
    D = data[3]

    data = np.fromfile('%s' % filename, dtype=np.float32)
    a = 7
    average = data[a:a + SR.item()]
    a = a + SR.item()
    coeff = data[a:a + D.item() * SR.item()].reshape((D.item(), SR.item()))
    a = a + D.item() * SR.item()
    scoredata = data[a:a + height.item() * width.item() * D.item()].reshape((height.item() * width.item(), D.item()))

    temp = np.dot(scoredata, coeff)
    data = (temp + average).reshape((height.item(), width.item(), SR.item()))

    # data = np.asnumpy(data)

    return data

