    """Load hyperspectral image from various formats.
    
    This transform handles loading of hyperspectral images from different
    file formats (.mat, .npy, .tif, .png) and normalizes them according
    to dataset-specific parameters.
    
    Required Keys:
    - img_path
    
    Modified Keys:
    - img
    - img_shape
    - ori_shape
    - img_path
    
    Args:
        dataset_type (str): Type of dataset ('harvard', 'umld2015', etc.)
        to_float32 (bool): Whether to convert to float32. Defaults to True.
        append_rgb (bool): Whether to append RGB channels. Defaults to False.
    """
    
    def __init__(
        self,
        dataset_type='harvard',
        to_float32=True,
        append_rgb=True,
        enable_rank_logging=False,
        rank_logger_cache: Optional[Dict[str, logging.Logger]] = None,
    ):
        self.dataset_type = dataset_type
        self.to_float32 = to_float32
        self.append_rgb = append_rgb
        self.enable_rank_logging = enable_rank_logging
        self.rank_logger_cache = rank_logger_cache
        
        # Dataset-specific parameters
        self._init_dataset_params()
        
        # Initialize wavelength information
        self._init_wavelength_params()
    
