        # Normalize data
        # data = (data - self.min) / (self.max - self.min)
        # data = (data - data.min()) / (data.max() - data.min())
        
        if self.append_rgb:
            # Create pseudo-RGB from spectral bands (using first 3 bands as placeholder)
            # Update with appropriate band indices for RGB representation
            if data.shape[2] >= 3:
                img_rgb = data[:, :,[51, 15, 6]]  # Using first 3 bands for RGB
