# Universal training pipeline for all datasets
def create_universal_train_pipeline(dataset_type, crop_size=(512, 512)):
    """Create a universal training pipeline for all hyperspectral datasets.
    
    Args:
        dataset_type (str): Type of dataset
        crop_size (tuple): Crop size for RandomCrop
        
    Returns:
        list: Training pipeline configuration
    """
    pipeline = [
        dict(type='LoadHyperspectralImage', dataset_type=dataset_type, to_float32=True, append_rgb=True),
        dict(type='LoadAnnotations', with_bbox=True, with_mask=True),
        # dict(type='RandomResize', scale=(512, 512), ratio_range=(0.5, 2.0), keep_ratio=True),
        # dict(type='RandomCrop', crop_size=crop_size),
        dict(type='RandomFlip', prob=.5),
        dict(type='PackDetInputs', meta_keys=('img_id', 'img_path', 'ori_shape', 'img_shape', 
                                                         'scale_factor', 'flip', 'flip_direction', 'wavelengths')),
    ]
    return pipeline


# Universal test pipeline for all datasets
def create_universal_test_pipeline(dataset_type):
    """Create a universal test pipeline for all hyperspectral datasets.
    
    Args:
        dataset_type (str): Type of dataset
        
    Returns:
        list: Test pipeline configuration
    """
    return [
        dict(type='LoadHyperspectralImage', dataset_type=dataset_type, to_float32=True, append_rgb=True),
        dict(type='LoadAnnotations', with_bbox=True, with_mask=True),
        dict(type='PackDetInputs', meta_keys=('img_id', 'img_path', 'ori_shape', 'img_shape', 
                                             'scale_factor', 'flip', 'flip_direction', 'wavelengths'))
    ]


